-- Public Data API grant hardening for the local review frontend.
--
-- Context:
--   Supabase Data API access is controlled by both GRANTs and RLS. The public
--   review frontend intentionally uses anon/authenticated roles, but these roles
--   should only receive the privileges each object actually needs.
--
-- This migration is intentionally conservative:
--   - keeps existing frontend reads and writes working
--   - keeps review RPC functions executable
--   - removes broad DELETE/TRUNCATE/trigger/reference/update grants that were
--     inherited from default public privileges
--   - keeps RLS policies as the row-level guardrail

-- Tables used by manual queue tags.
revoke all privileges on table public.product_tags from anon, authenticated;
grant select, insert on table public.product_tags to anon, authenticated;

revoke all privileges on table public.product_tag_assignments from anon, authenticated;
grant select, insert, update on table public.product_tag_assignments to anon, authenticated;

-- Tables used by Sellpia latest-stock upload from the frontend.
revoke all privileges on table public.sellpia_stock_snapshots from anon, authenticated;
grant select, insert, update on table public.sellpia_stock_snapshots to anon, authenticated;

revoke all privileges on table public.sellpia_stock_snapshot_rows from anon, authenticated;
grant select, insert on table public.sellpia_stock_snapshot_rows to anon, authenticated;

-- Tables used by Sellpia product/option shared tags.
revoke all privileges on table public.sellpia_tag_assignments from anon, authenticated;
grant select, insert, update on table public.sellpia_tag_assignments to anon, authenticated;

-- Public read views should remain read-only through the Data API.
revoke all privileges on table public.match_candidate_queue_sample from anon, authenticated;
grant select on table public.match_candidate_queue_sample to anon, authenticated;

revoke all privileges on table public.match_candidate_details_sample from anon, authenticated;
grant select on table public.match_candidate_details_sample to anon, authenticated;

revoke all privileges on table public.mapping_matrix_review_sample_v2 from anon, authenticated;
grant select on table public.mapping_matrix_review_sample_v2 to anon, authenticated;

revoke all privileges on table public.mapping_matrix_review_sample_v3 from anon, authenticated;
grant select on table public.mapping_matrix_review_sample_v3 to anon, authenticated;

revoke all privileges on table public.match_candidate_queue_full from anon, authenticated;
grant select on table public.match_candidate_queue_full to anon, authenticated;

revoke all privileges on table public.match_candidate_details_full from anon, authenticated;
grant select on table public.match_candidate_details_full to anon, authenticated;

revoke all privileges on table public.mapping_matrix_review_full_v2 from anon, authenticated;
grant select on table public.mapping_matrix_review_full_v2 to anon, authenticated;

revoke all privileges on table public.mapping_matrix_review_full_v3 from anon, authenticated;
grant select on table public.mapping_matrix_review_full_v3 to anon, authenticated;

revoke all privileges on table public.sellpia_stock_latest from anon, authenticated;
grant select on table public.sellpia_stock_latest to anon, authenticated;

revoke all privileges on table public.sellpia_products_public from anon, authenticated;
grant select on table public.sellpia_products_public to anon, authenticated;

revoke all privileges on table public.sellpia_product_images_public from anon, authenticated;
grant select on table public.sellpia_product_images_public to anon, authenticated;

revoke all privileges on table public.product_images_resolved from anon, authenticated;
grant select on table public.product_images_resolved to anon, authenticated;

-- Keep the explicitly designed RPC surface for review mode.
revoke all privileges on function public.update_match_candidate_queue_cell(bigint, text, text, text, text)
  from public, anon, authenticated;
grant execute on function public.update_match_candidate_queue_cell(bigint, text, text, text, text)
  to anon, authenticated;

revoke all privileges on function public.link_match_candidate_option(bigint, text, text, text, text, text, text)
  from public, anon, authenticated;
grant execute on function public.link_match_candidate_option(bigint, text, text, text, text, text, text)
  to anon, authenticated;

revoke all privileges on function public.unlink_match_candidate_option(bigint, text, text)
  from public, anon, authenticated;
grant execute on function public.unlink_match_candidate_option(bigint, text, text)
  to anon, authenticated;
